css:
.loader { position: relative; overflow: hidden; width: var(--loader-size); height: calc(var(--loader-size) * .06); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color) 18%, transparent); }
.loader span { position: absolute; top: 0; bottom: 0; left: 0; width: 40%; border-radius: 9999px; background: var(--loader-color); animation: twSlide calc(var(--loader-speed) * 1.4) ease-in-out infinite; }
@keyframes twSlide { 0% { transform: translateX(-110%); } 100% { transform: translateX(280%); } }
